(()=>{
'use strict';
const DATA=window.K417_DATA;
const {PEOPLE,EVIDENCE,INSPECTIONS,SEARCH_DOCS,DEDUCTION_RECIPES,STAGES,FINAL_FIELDS}=DATA;
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>Array.from(r.querySelectorAll(s));
const SAVE_KEY='k417_rebuild_v3';
const VERSION='5.0.0';
const TIME_OFFSET=6, BOX_CODE='0618';
const endingFromChoices=(tape,archive)=>tape==='copy'&&archive==='leak'?'truth':tape==='seize'&&archive==='seal'?'legal':'protect';
const LOCS={
  cabin:{name:'6车·7号包厢',desc:'案发现场。所有物体先检查、记录，再决定是否登记为证物。',records:['S10']},
  dining:{name:'8车·餐车',desc:'独立收银时钟和夜班人员能提供相对可靠的时间锚点。',records:['R01']},
  conductor:{name:'9车·乘务室',desc:'巡检、供电、广播、法医传真和席位记录集中在这里。',records:['R02','R03','R10','R04','R05','F01','F02','F04','F05']},
  corridor:{name:'5—6车连接处',desc:'玻璃反光、地毯和过道人流能打破“只有一个人进出”的假设。',records:['R06','R09']},
  car4:{name:'4车·行李架',desc:'人员物品、药品登记与一把被擦过的折叠刀。',records:['R07','F06']}
};
const NAV=[['case','案情','案'],['map','列车调查','查'],['people','证人质询','证'],['evidence','证物与推理','推'],['search','旧网检索','网'],['timeline','时间轴','时'],['puzzles','特殊检验','验'],['final','终夜结案','结']];
const norm=s=>String(s||'').toLowerCase().replace(/[\s·，。、“”‘’：:；;（）()\/\\_-]/g,'');
const clone=o=>JSON.parse(JSON.stringify(o));
function baseState(){return {version:VERSION,started:false,route:'case',stage:1,evidence:[],deductions:[],inspection:{},interviews:{},confrontAttempts:{},person:'lin',searchHistory:[],openDocs:[],timeSolved:false,photoSolved:false,photoEdgeFound:false,boxOpened:false,finalSubmitted:false,finalAnswers:{},ending:null,selectedCombine:[],audio:false,hints:0,hintTier:1,hintContext:'',choices:{},logs:[{t:'01:47',text:'暴雪迫停K417。6车7号包厢内发现周柏年死亡，现场暂时封锁。'}],activeLocation:'cabin',modal:null,secret:false,startedAt:Date.now()};}
let state=load();
let bootCover=true;
let autoPayScheduled=false;
function load(){try{const x=JSON.parse(localStorage.getItem(SAVE_KEY)||'null');if(x&&['3.0.0','4.0.0','5.0.0'].includes(x.version)){const s=Object.assign(baseState(),x);s.version=VERSION;s.confrontAttempts=s.confrontAttempts||{};return s}}catch(e){}return baseState();}
function save(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));}catch(e){}}
function savedExists(){try{return !!localStorage.getItem(SAVE_KEY)}catch(e){return false}}
function hasEv(id,s=state){return s.evidence.includes(id)}
function hasDed(id,s=state){return s.deductions.includes(id)}
function hasAny(id,s=state){return id.startsWith('D')?hasDed(id,s):hasEv(id,s)}
function addLog(text,t=''){state.logs.unshift({t:t||['02:02','02:18','02:37','03:04','03:21','03:48','04:16'][Math.max(0,state.stage-1)]||'--:--',text});state.logs=state.logs.slice(0,14)}
function toast(text,kind=''){let wrap=$('.toastwrap');if(!wrap){wrap=document.createElement('div');wrap.className='toastwrap';document.body.appendChild(wrap)}const n=document.createElement('div');n.className='toast '+kind;n.textContent=text;wrap.appendChild(n);setTimeout(()=>n.remove(),2900)}
function playSfx(id){if(!state.audio)return;const a=$('#sfx-'+id);if(a){try{a.currentTime=0;a.volume=.35;a.play().catch(()=>{})}catch(e){}}}
function addEvidence(id,msg=true){if(!EVIDENCE[id]||hasEv(id))return false;state.evidence.push(id);if(msg)toast('证物登记：'+EVIDENCE[id].name,'good');playSfx('paper');refreshStage();save();return true}
function addDeduction(id,msg=true){const d=DEDUCTION_RECIPES.find(x=>x.id===id);if(!d||hasDed(id))return false;state.deductions.push(id);if(msg)toast('推理成立：'+d.name,'good');addLog('推理板确认：'+d.name);playSfx('paper');refreshStage();save();return true}
function interviewStats(s=state){const pids=Object.keys(s.interviews||{});const people=pids.filter(id=>Object.keys(s.interviews[id]||{}).length>0).length;const conf=Object.values(s.interviews||{}).reduce((n,o)=>n+Object.keys(o||{}).filter(k=>k.startsWith('c:')&&o[k]).length,0);return {people,conf}}
function oldCaseCount(s=state){return s.evidence.filter(id=>/^O/.test(id)).length}
function inspectionCount(s=state){return Object.values(s.inspection||{}).filter(x=>x&&x.registered).length}
function computeStage(s){let stage=1;const its=inspectionCount(s), ins=interviewStats(s);if(its>=5&&['R01','R02','R03'].filter(x=>hasEv(x,s)).length>=2)stage=2;if(stage>=2&&ins.people>=4&&hasEv('R06',s)&&hasEv('R10',s))stage=3;if(stage>=3&&oldCaseCount(s)>=3)stage=4;if(stage>=4&&s.timeSolved&&hasDed('D02',s))stage=5;if(stage>=5&&hasDed('D03',s)&&hasDed('D04',s))stage=6;if(stage>=6&&ins.conf>=3&&s.photoSolved&&s.boxOpened)stage=7;if(stage>=7&&['P14','P20','P22'].every(x=>hasEv(x,s))&&hasDed('D10',s))stage=8;return stage}
function refreshStage(){const old=state.stage;const n=computeStage(state);if(n>old){state.stage=n;const st=STAGES[n-1];addLog('调查进入第'+n+'阶段：'+st.title);playSfx('brake');toast('调查推进：'+st.title,'good')}save()}
function visibleEvidence(id){const e=EVIDENCE[id];if(!e)return false;if(id==='R09'&&state.stage<4)return false;if(/^F0[1-3]$/.test(id)&&state.stage<4)return false;if(/^F0[4-6]$/.test(id)&&state.stage<5)return false;if(['R04','R05'].includes(id)&&state.stage<3)return false;return (e.stage||1)<=Math.max(state.stage,1)}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function progress(){const raw=state.evidence.length+state.deductions.length*2;return Math.min(100,Math.round(raw/78*100))}
function hintProfile(){
  const its=inspectionCount(),ins=interviewStats(),records=['R01','R02','R03'].filter(x=>hasEv(x)).length;
  if(state.stage===1&&its<5)return {key:`s1-ins-${its}`,title:'先把现场变成事实',levels:['不要先猜“谁杀了人”。第一阶段最重要的是把包厢里的可见事实固定下来。','包厢里至少完成5项物证检查；每件物体都要先看两个以上局部，再写下观察。','优先检查腕表、茶杯、药盒、门锁和血迹。记录“时间/撞痕、杯内残留、具体药名、锁具磨痕、出血量”这类原始事实。']};
  if(state.stage===1&&records<2)return {key:`s1-rec-${records}`,title:'给现场找独立记录',levels:['只靠包厢内部物证无法建立完整时间与行动背景，需要离开现场找独立记录。','餐车与乘务室都保存了不依赖死者包厢的原始记录，至少取得其中两份。','去8车餐车查看收银记录；再去9车乘务室查看巡检/供电/广播等记录。']};
  if(state.stage===2&&ins.people<4)return {key:`s2-people-${ins.people}`,title:'扩大证人样本',levels:['不要只盯着最可疑的人。先让不同位置、不同关系的人都留下基础口供。','至少询问4名相关人员，优先覆盖不同车厢和不同旧案关系。','可先询问林婉、陈川、顾言、徐洛；问完基础问题后再拿照片、票据或日志质证具体一句话。']};
  if(state.stage===2&&(!hasEv('R06')||!hasEv('R10')))return {key:`s2-anchor-${hasEv('R06')?'1':'0'}${hasEv('R10')?'1':'0'}`,title:'补齐人物移动锚点',levels:['人物口供需要被独立资料约束，否则每个人都可以重新讲一遍自己的路线。','你还缺能固定人物位置或移动的独立照片/席位资料。','去5—6车连接处找徐洛相机原片（R06），并去9车乘务室取得席位记录（R10）。']};
  if(state.stage===3&&oldCaseCount()<3)return {key:`s3-old-${oldCaseCount()}`,title:'让1994年旧案落到原始材料',levels:['旧案不能只靠证人口述。先用旧网找到彼此独立的公开残页。','搜索时尽量使用完整人名、机构名和年份，不要只输入一个泛词。','可从“安济 1994”“顾明远”“方琴 安济”“韩雪琴 1994”等组合入手，至少保存3份真正与旧案有关的材料。']};
  if(state.stage===4&&!state.timeSolved)return {key:'s4-time',title:'先找可信时钟，再算偏移',levels:['时间谜题的关键不是做减法，而是判断“哪一个设备的时间值得相信”。','录像机经历过供电切换；徐洛相机有独立校时依据。先解释为什么录像机会整体偏移。','取得R04录像启动日志、R05供电切换单、R06相机原片。用相机01:23附近锚定录像01:29，并连续换算01:32、01:34；偏移量应保持一致。']};
  if(state.stage===5&&!hasDed('D03'))return {key:'s5-drug',title:'重建药物作用链',levels:['把“现场发现了药”和“药导致死亡”分开。你需要既往用药、新摄入物与专业机制三类支点。','茶杯/药盒只能证明现场存在什么；毒理与专业意见才能证明相互作用。','把S03茶杯残留、S08药盒、F02毒理、F03药物相互作用意见中能分别承担“摄入/既往用药/机制”的材料放上推理板。']};
  if(state.stage===5&&!hasDed('D04'))return {key:'s5-wound',title:'判断刀伤是不是主要死因',levels:['不要因为现场有刀伤就自动把它当成死亡原因。比较出血量、活体反应和法医结论。','如果伤口是在死亡后形成，通常会缺少与活体循环相符的反应。','把S06血迹、F01法医初检，以及能说明真实死亡机制的材料放在一起；目标是证明“刺伤发生了，但不是主要死因”。']};
  if(state.stage===6&&ins.conf<3)return {key:`s6-conf-${ins.conf}`,title:'把口供压到具体一句话上',levels:['现在缺的不是更多闲聊，而是让关键人物在证物面前改口。','选择已经取得的材料去质证对应问题；有些关键口供需要两到四项材料共同闭合。','优先处理与下药、未施救、进入包厢有关的矛盾。错误质证两次后，系统会提示你缺的是哪一类支点。']};
  if(state.stage===6&&!state.photoSolved)return {key:`s6-photo-${state.photoEdgeFound?'edge':'scan'}`,title:'照片里少的不是“数字”',levels:['先看照片本身，不要直接输入“第十三人”。真正的证据是裁切边缘留下了什么。','把鼠标移到1994照片左缘，寻找二次裁切区域；看清残留物后再判断最少人数。','左缘切口穿过人物轮廓，残留半截袖口和圆形金属徽章；结合现存十二人，原画面至少还有一人。']};
  if(state.stage===6&&!state.boxOpened)return {key:'s6-box',title:'密码箱要先算中间量',levels:['手写提示“留下的人 / 那一天”包含两个不同来源的信息，不能直接猜四位数。','“留下的人”来自受试者总数减死亡人数；“那一天”来自事故实际发生日，不是新闻发布日期。','旧案登记残页给出7名受试者、1人死亡，因此留下6人；公开报道核实事故实际发生在18日。按提示组合为两位人数+两位日期。']};
  if(state.stage===7&&!['P14','P20','P22'].every(x=>hasEv(x)))return {key:'s7-statements',title:'最后不是找一个“凶手”',levels:['终局前要把三种行为分别坐实：下药、未施救、刺伤。它们不是同一个法律和事实问题。','继续质证相关人物，目标是取得三份互相独立的责任证词，而不是让某一个人承担全部行为。','需要形成P14、P20、P22三类关键口供：谁改变了饮品、谁发现仍可救却没有呼救、谁实施了之后的刺伤。']};
  if(state.stage===7&&!hasDed('D10'))return {key:'s7-d10',title:'把三种责任拆开',levels:['证词齐了以后，不要再把案件压回“单一凶手”模型。','把下药、未施救、死后刺伤分别作为独立事实，再看它们如何共同造成密室表象。','将三份关键责任口供与已经成立的死因/刀伤/密室推论放上推理板，确认D10责任拆分。']};
  if(state.stage===8&&!finalReady())return {key:'s8-chain',title:'终局只接受闭合事实链',levels:['终局不是猜人名，而是检查死亡机制、刀伤性质、密室形成、可救治窗口和责任拆分是否都已被证明。','回到推理板，看看是否还有“已拿到材料但没有形成推论”的链条。','优先确认D03药物作用、D04刀伤性质、D05/D06密室与多人进入、可救治窗口，以及D10责任拆分。']};
  if(state.stage===8&&!state.finalSubmitted)return {key:'s8-final',title:'用短事实填写结案表',levels:['每一栏只写证据已经支持的事实，不需要文学化描述。','如果系统判错，检查是否把“死亡原因”和“刺伤行为”混写在同一栏。','分别填写药物相互作用导致死亡、下药者、未施救者、死后刺伤者、外部复位门锁/多人进入等对应事实。']};
  return {key:`s${state.stage}-done`,title:'当前阶段已基本闭合',levels:['你已经完成当前最关键的事实链。可以检查案情总览里的未完成目标。','如果没有明显缺项，去“证物与推理板”查看仍未组合的材料，或去“特殊检验/终夜结案”完成后续。','三级提示不会替你自动登记证物；若卡住，优先看案情总览中仍未打勾的目标，再回到对应页面完成。']};
}
function syncHintContext(){const h=hintProfile();if(state.hintContext!==h.key){state.hintContext=h.key;state.hintTier=1;save()}return h}
function supportConfig(){return {qrCode:'assets/images/paycode.png',price:'1元',title:'支持《红夜列车》',studio:'abc studio'}}
function scheduleAutoPay(){if(autoPayScheduled||!window.Paywall)return;autoPayScheduled=true;window.Paywall.autoShow(supportConfig(),1200)}
function shell(content){const st=STAGES[state.stage-1];const hint=syncHintContext();const weather=['暴雪持续','风雪增强','车外 -8℃','山区无信号'];const status=state.stage<4?'列车停留 · 现场封锁':state.stage<7?'供电记录已封存 · 录像离线':'天亮前 约2小时 · 江港方向待通行';return `<div class="shell route-${state.route}"><header class="topbar"><div class="case-mark">K417 <small>临时刑事调查卷 · 2008.01.19</small></div><div class="stage-tape">卷标 ${state.stage}/8 · ${st.title}</div><div class="spacer"></div><div class="topmeta">已封存 ${state.evidence.length} 件 · 推论 ${state.deductions.length} 条</div><div class="top-actions"><button class="hint-trigger" data-hint title="根据当前调查进度给出三级递进提示"><span>提示</span><b>${state.hintTier||1}/3</b></button><button class="support-trigger ${window.Paywall?.hasPaid?.()?'supported':''}" data-support>${window.Paywall?.hasPaid?.()?'已支持':'支持作品'}</button><button class="sound ${state.audio?'on':''}" data-audio>${state.audio?'车厢声 ON':'车厢声 OFF'}</button></div></header><div class="rail-status"><span>${status}</span><span>${weather[state.stage%weather.length]}</span><span>车载网：离线</span><span>调查终端：K417-09</span><span>当前提示：${esc(hint.title)}</span></div><div class="workspace"><aside class="side"><div class="side-label">K417 / CASE FILE</div><nav class="nav">${NAV.map((n,i)=>`<button data-route="${n[0]}" data-short="${n[2]}" class="${state.route===n[0]?'active':''}"><span class="num">${String(i+1).padStart(2,'0')}</span><span class="label">${n[1]}</span></button>`).join('')}</nav><div class="side-progress">卷宗完整度 ${progress()}%<div class="track"><i style="width:${progress()}%"></i></div></div></aside><main class="main">${content}</main></div></div>${renderModal()}`}

function pageHead(title,sub,tag=''){return `<div class="pagehead"><div><h1>${title}</h1><p>${sub}</p></div>${tag?`<span class="tag">${tag}</span>`:''}</div>`}
function splash(){const hasSave=savedExists()&&state.started;const meta=hasSave?`检测到上次存档：卷标 ${state.stage}/8 · ${STAGES[state.stage-1]?.title||'调查中'} · 已封存 ${state.evidence.length} 件证物`:'尚未建立本机调查档案。点击“开始案情”将从封锁现场开始。';return `<div class="splash cover-screen"><div class="splash-bg"></div><div class="snow"></div><section class="splash-card cover-card"><div class="cover-file-tab">K417 / CASE 071 / TEMPORARY DOSSIER</div><div class="kicker">K417 · NORTHBOUND · 2008</div><h1>北纬七码·终夜列车</h1><div class="case-tag">暴雪 · 封闭列车 · 旧案重启</div><p class="sub">凌晨1:47，K417被暴雪迫停。医疗集团负责人周柏年死在反锁包厢。十二名乘客与1994年的一宗医疗事故同时出现在这列车上。你需要检查物体、记录异常、校准时间、质证口供并重建责任链。</p><div class="cover-status ${hasSave?'saved':'new'}"><b>${hasSave?'已有调查档案':'新调查档案'}</b><span>${meta}</span></div><div class="actions cover-actions"><button class="btn primary cover-primary" data-enter-case>开始案情</button><button class="btn paper" data-reset-case>重置案情</button><button class="btn" data-help>调查说明</button></div><div class="cover-note"><b>操作说明</b><span>“开始案情”会读取本机已有进度；“重置案情”会清空当前案件进度并从第一阶段重新开始。</span><span>进入调查后，页面上方提供三级动态提示与“支持作品”入口。</span></div><div class="foot">建议使用耳机。所有核心信息均有文字等价内容，关闭声音不会影响通关。</div></section></div>${renderModal()}`}

function objectives(){const s=state.stage;const list=s===1?[[inspectionCount()>=5,'完成至少5项现场物证检查','必须查看局部并写下自己的观察'],[['R01','R02','R03'].filter(x=>hasEv(x)).length>=2,'取得至少2份独立列车记录','餐车、乘务室均可查']]:s===2?[[interviewStats().people>=4,'询问至少4名相关人员','先问基础口供，再拿材料质证'],[hasEv('R06')&&hasEv('R10'),'取得独立照片与席位表','建立人物移动基础']]:s===3?[[oldCaseCount()>=3,'从旧网找到至少3份1994原始材料','不要依赖推荐关键词'],[hasEv('O03')||hasEv('O04'),'把旧案资料用于一次质证','证词只有被材料击穿才算有效']]:s===4?[[state.timeSolved,'校准录像时间','需要供电日志、录像启动日志、徐洛原片'],[hasDed('D02'),'确认监控时钟偏移','输入偏移而非选择答案']]:s===5?[[hasDed('D03'),'重建药物作用链','组合现场、毒理与专业意见'],[hasDed('D04'),'判断刀伤是否为主要死因','比较失血与活体反应']]:s===6?[[interviewStats().conf>=3,'完成至少3次有效质证','用具体证物而不是猜测'],[state.photoSolved,'确认旧照片被裁去的人','直接检查裁切边缘'],[state.boxOpened,'打开床下密码箱','密码来自旧案人数信息']]:s===7?[[['P14','P20','P22'].every(x=>hasEv(x)),'取得三份关键责任证词','分别确认下药、未施救、刺伤'],[hasDed('D10'),'把三种行为拆开归责','不要压缩成“一个凶手”']]:[[true,'事实链已完整','进入终夜结案'],[state.secret,'查明“第十三人”','可选隐藏调查']];return `<div class="objectives"><div class="section" style="margin-top:0">本阶段目标</div>${list.map(x=>`<div class="obj ${x[0]?'done':''}"><div class="check">${x[0]?'✓':''}</div><div><b>${x[1]}</b><small>${x[2]}</small></div></div>`).join('')}</div>`}
function renderCase(){const st=STAGES[state.stage-1];const choiceA=state.choices.tape?`磁带处理：${state.choices.tape==='seize'?'依法扣押原件':'复制后归还顾言'}`:'';const choiceB=state.choices.archive?`旧案材料：${state.choices.archive==='seal'?'先封存待正式移交':'允许记者保留一份备份'}`:'';return pageHead('案情总览','这里保存调查目标、关键节点和你主动做出的程序选择。','K417 / 终夜')+`<div class="case-grid"><section class="brief"><span class="stamp">现场封锁</span><h2>${st.title}</h2><p>${st.desc}</p><p><b>当前原则：</b>原始材料与推断分开保存。证物库只登记观察到的事实，推理结果单独进入推理板。</p>${hasEv('P05')&&!state.choices.tape?`<div class="sep"></div><b>原始采访磁带如何处理？</b><div class="actions"><button class="btn paper" data-choice="tape:seize">扣押原件并封存</button><button class="btn paper" data-choice="tape:copy">复制校验后归还</button></div>`:''}${state.boxOpened&&!state.choices.archive?`<div class="sep"></div><b>密码箱旧案材料如何处理？</b><div class="actions"><button class="btn paper" data-choice="archive:seal">全部封存移交</button><button class="btn paper" data-choice="archive:leak">允许保留备份</button></div>`:''}${choiceA||choiceB?`<div class="sep"></div><div class="tiny">${[choiceA,choiceB].filter(Boolean).join('<br>')}</div>`:''}</section><div>${objectives()}<section class="log"><h3>调查记录 / EVENT LOG</h3>${state.logs.map(l=>`<div class="logline"><time>${esc(l.t)}</time><p>${esc(l.text)}</p></div>`).join('')}</section></div></div>`}
function trainStrip(){return `<div class="train">${[2,3,4,5,6,7,8,9].map(n=>`<div class="car ${n===6?'target':''}"><strong>${n}车</strong><span>${n===6?'案发包厢所在':'乘客与公共区域'}</span></div>`).join('')}</div>`}
function recordButton(id){const e=EVIDENCE[id];if(!e||!visibleEvidence(id))return '';return `<div class="record"><div><b>${esc(e.name)}</b><em>${esc(e.type)}</em></div>${hasEv(id)?'<span class="tiny">已登记</span>':`<button class="btn sm" data-read-ev="${id}">查阅</button>`}</div>`}
function renderMap(){const loc=LOCS[state.activeLocation]||LOCS.cabin;return pageHead('列车调查','先定位、再观察、最后登记。现场物证不会因为“点到热点”自动进入证物库。','现场封锁中')+trainStrip()+`<div class="section">调查位置</div><div class="locgrid">${Object.entries(LOCS).map(([id,l])=>`<button class="loc ${state.activeLocation===id?'active':''}" data-loc="${id}"><h4>${l.name}</h4><p>${l.desc}</p></button>`).join('')}</div><div class="section">${loc.name}</div>${state.activeLocation==='cabin'?`<div class="scene-grid"><div class="scene"><img src="assets/images/cabin_scene.jpg" alt="7号包厢案发现场">${INSPECTIONS.map(it=>{const r=state.inspection[it.id]?.registered;return `<button class="hot ${r?'found':''}" data-inspect="${it.id}" aria-label="检查${it.label}" style="left:${it.pos[0]}%;top:${it.pos[1]}%;width:${it.pos[2]}%;height:${it.pos[3]}%"><span>${it.label}</span></button>`}).join('')}</div><aside class="scene-note"><h3>现场原则</h3><p class="tiny">热点只代表“可以靠近检查”。打开物体后至少观察两个局部，再用自己的话记录异常。系统只判断你是否捕捉到关键事实，不要求固定完整句子。</p>${recordButton('S10')}<div class="sep"></div><div class="tiny">已完成现场检查 ${inspectionCount()}/${INSPECTIONS.length}</div></aside></div>`:`<section class="location"><h3>${loc.name}</h3><p class="tiny">${loc.desc}</p>${loc.records.map(recordButton).join('')||'<p class="tiny">此处暂时没有新的可核验材料。</p>'}</section>`}`}
function asked(pid,qid){return !!state.interviews[pid]?.[qid]}
function personProgress(pid){return Object.keys(state.interviews[pid]||{}).filter(k=>!k.startsWith('c:')).length}
function acquiredOptions(){const evs=state.evidence.map(id=>{const e=EVIDENCE[id]||{};return `<option value="${id}">${esc(e.name||id)} · ${esc(e.where||'来源待核')}</option>`});const ds=state.deductions.map(id=>{const d=DEDUCTION_RECIPES.find(x=>x.id===id)||{};return `<option value="${id}">推论：${esc(d.name||id)}</option>`});return '<option value="">选择用于质证的材料…</option>'+evs.concat(ds).join('')}
function confrontPaths(c){if(!c)return[];const raw=c[1];if(!Array.isArray(raw))return [[raw]];if(raw.length&&Array.isArray(raw[0]))return raw;return raw.map(x=>[x])}
function confrontControls(qid,c){const paths=confrontPaths(c);const slots=Math.min(4,Math.max(1,...paths.map(p=>p.length)));return `<div class="confront-tray"><div class="confront-label">质证材料夹 · 可放 ${slots} 项（空槽可不填）</div><div class="confront-slots">${Array.from({length:slots},(_,i)=>`<select class="evselect" data-confront-select="${qid}" aria-label="质证材料${i+1}">${acquiredOptions()}</select>`).join('')}</div><button class="btn sm paper" data-confront="${qid}">提交质证链</button></div>`}
function renderPeople(){const p=PEOPLE.find(x=>x.id===state.person)||PEOPLE[0];const pc=personProgress(p.id);const mood=pc===0?'尚未建立有效交流':pc<p.q.length?'回答开始出现细节变化':'基础询问已完成，可集中质证';return pageHead('证人质询','证词不是答案。先把人物说完整，再把票据、照片、日志或已成立推论压到具体一句话上。关键口供可能需要两到四项材料共同闭合。',`${interviewStats().people}/12 已询问`)+`<div class="people-layout"><div class="people-list">${PEOPLE.map(x=>`<button class="person-row ${x.id===p.id?'active':''}" data-person="${x.id}"><img src="assets/images/${x.portrait}" alt="${x.name}证件照"><div><b>${x.name}</b><small>${x.age}岁 · ${x.role}<br>${personProgress(x.id)}/${x.q.length} 已询问</small></div></button>`).join('')}</div><article class="dossier"><div class="dhead"><div class="portrait"><img src="assets/images/${p.portrait}" alt="${p.name}档案照片"><div class="file-no">WITNESS / ${p.id.toUpperCase()} / ${p.seat}</div><div class="portrait-note">${esc(p.portraitNote||'K417 临时身份核验照')}</div></div><div><span class="stamp">证人档案</span><h2>${p.name}</h2><div class="idline">年龄 ${p.age}　职业 ${p.role}　席位 ${p.seat}</div><p>${p.summary}</p><div class="relation"><b>已知关系</b><br>${p.relation}</div><div class="dossier-mood"><b>当前访谈状态</b> · ${mood}</div>${p.signals?.length?`<div class="behavior-notes"><b>访谈员观察</b>${p.signals.map(s=>`<span>· ${esc(s)}</span>`).join('')}</div>`:''}</div></div><section class="statement-area"><div class="section" style="color:#5d4d34">基础询问 / 逐题记录</div>${p.q.map(q=>`<div class="statement"><b>${q[1]}</b>${asked(p.id,q[0])?`<p>${q[2]}</p><div class="sactions">${(()=>{const c=p.c.find(x=>x[0]===q[0]);if(!c)return'<span class="tiny">此回答暂时只能作为口供保留。</span>';const done=asked(p.id,'c:'+q[0]);return done?`<span class="break">✓ 质证后形成：${esc(EVIDENCE[c[2]]?.name||c[2])}</span>`:confrontControls(q[0],c)})()}</div>`:`<p class="tiny">尚未形成笔录。</p><button class="btn sm paper" data-ask="${q[0]}">询问</button>`}</div>`).join('')}</section></article></div>`}
function renderEvidence(){const types=['全部',...Array.from(new Set(state.evidence.map(id=>EVIDENCE[id]?.type).filter(Boolean)))];const f=state.evFilter||'全部';const evs=state.evidence.filter(id=>f==='全部'||EVIDENCE[id]?.type===f);const selectedRoles=state.selectedCombine.map(id=>{const e=EVIDENCE[id];const d=DEDUCTION_RECIPES.find(x=>x.id===id);return `<span>${esc(e?.type||'已确认推论')} · ${esc(e?.where||d?.name||id)}</span>`}).join('');return pageHead('证物与推理板','只把原始观察与被材料击穿后的陈述放进卷宗。系统按“证据角色”核验因果，而不是要求唯一卡牌配方。',`${state.evidence.length} 证物 / ${state.deductions.length} 推理`)+`<div class="folderbar">${types.map(t=>`<button class="folder ${f===t?'active':''}" data-filter="${esc(t)}">${esc(t)}</button>`).join('')}</div>${evs.length?`<div class="evgrid">${evs.map(id=>{const e=EVIDENCE[id];const sel=state.selectedCombine.includes(id);return `<article class="evcard" data-id="${id}"><i class="pin"></i><div class="etype">${e.type} · ${e.where}</div><h3>${e.name}</h3><p>${e.desc}</p><button class="btn sm ${sel?'primary':'paper'}" data-combine="${id}">${sel?'已放入推理板':'放入推理板'}</button></article>`}).join('')}</div>`:'<p class="tiny">这一分类还没有登记材料。</p>'}<div class="section">推理板</div><section class="board"><div class="tiny">一次最多放入5项材料。系统检查的是“事实角色是否闭合”：例如既往用药 / 新摄入药物 / 专业机制，而不是某一个固定编号组合。</div><div class="slots">${state.selectedCombine.length?state.selectedCombine.map(id=>`<button class="chip" data-combine="${id}">${esc((EVIDENCE[id]||DEDUCTION_RECIPES.find(d=>d.id===id)||{}).name||id)} ×</button>`).join(''):'<span class="tiny">把你认为属于同一条事实链的材料放进来……</span>'}</div>${selectedRoles?`<div class="board-roles">${selectedRoles}</div>`:''}<div class="actions"><button class="btn primary" data-deduce ${state.selectedCombine.length<2?'disabled':''}>验证关联</button><button class="btn" data-clear-combine>清空</button></div><div class="section">已确认推理</div>${state.deductions.length?state.deductions.map(id=>{const d=DEDUCTION_RECIPES.find(x=>x.id===id);const sel=state.selectedCombine.includes(id);return `<div class="ded"><h4>${d.name}</h4><p>${d.text}</p><button class="btn sm paper" data-combine="${id}">${sel?'移出推理板':'继续用于上层推理'}</button></div>`}).join(''):'<p class="tiny">还没有经材料组合确认的推理。</p>'}</section>`}
function searchResults(q){const raw=String(q||'').trim();const parts=raw.split(/\s+/).map(norm).filter(Boolean);if(!parts.length)return[];const scored=SEARCH_DOCS.map(d=>{const title=norm(d.title);const keys=d.keys.map(norm);let score=0,matched=0;parts.forEach(part=>{let hit=0;if(title.includes(part)){hit=Math.max(hit,5)};keys.forEach(k=>{if(k===part)hit=Math.max(hit,6);else if(k.includes(part)||part.includes(k))hit=Math.max(hit,4)});if(hit){score+=hit;matched++}});if(parts.length>1&&matched===parts.length)score+=4;return {d,score,matched}}).filter(x=>x.score>=4).sort((a,b)=>b.score-a.score||b.matched-a.matched||b.d.date.localeCompare(a.d.date));return scored.slice(0,10).map(x=>x.d)}
function resultsNeedDecoys(){return false}
function renderSearch(){const latest=state.searchHistory[0]||'';const results=latest?searchResults(latest):[];const hidden=state.boxOpened&&['沈世勋','资金负责人','第十三人'].some(k=>norm(latest).includes(norm(k)));return pageHead('旧网检索','2008年离线缓存镜像。索引里混有同名人物、同名机构、行业资料与真正的旧案残页，需要自己判断来源。','离线缓存终端')+`<div class="crt"><div class="crt-top">K417 调查终端 - Microsoft Internet Explorer 6</div><div class="crt-menu">文件(F)　编辑(E)　查看(V)　收藏(A)　工具(T)　帮助(H)</div><div class="crt-body"><form class="searchbar" data-search><input name="q" autocomplete="off" value="${esc(latest)}" placeholder="输入人名、机构、年份或职务；空格可组合多个词"><button>搜索</button></form><div class="search-help">本地索引共 ${SEARCH_DOCS.length} 条缓存记录。结果按词组匹配排序，不再用单个汉字重合强行召回。</div>${latest?`<div class="tiny" style="color:#444">检索：“${esc(latest)}” · ${results.length+(hidden?1:0)} 条可能相关</div>`:''}${hidden?`<div class="sresult"><h3><button class="linkbtn" data-secret-doc>缓存索引：安济项目资金审批人（缺页）</button></h3><div class="meta">1994-11 · 内部索引残留</div><p>索引字段仅剩：沈世勋 / 项目资金 / 临时批示。</p></div>`:''}${results.map(d=>`<div class="sresult"><h3><button class="linkbtn" data-doc="${d.id}">${esc(d.title)}</button></h3><div class="meta">${d.date} · ${d.kind}</div><p>${esc(d.snippet)}</p></div>`).join('')}${latest&&!results.length&&!hidden?'<p>没有足够接近的索引项。尝试减少一个词，或改用材料里出现过的完整人名、机构名与年份。</p>':''}</div><div class="crt-status">本地缓存模式 · 结果可能残缺 · 同名记录不代表同一主体</div></div>`}
function renderTimeline(){const unlocked=hasEv('R04')&&hasEv('R05')&&hasEv('R06');const events=[['01:12','餐车收银：周柏年下单黑咖啡'],['01:16','餐车记录：咖啡送达'],['01:17','列车供电切换；录像设备掉电'],['01:18','死者手机保存未发送草稿'],['01:19','林婉在餐车结账'],['01:23:41','徐洛相机：连接处反光人影'],['01:24','列车第一次制动提示'],['01:26','乘务巡检记录7号包厢门锁闭'],['01:47','暴雪迫停，尸体随后被发现']];return pageHead('时间轴校准','先确认哪个时钟可信，再解释偏移为什么发生，最后把整段录像换算到同一基准。','独立时钟优先')+`<div class="timeline">${events.map(e=>`<div class="trow"><time>${e[0]}</time><div class="tevent"><b>${e[1]}</b><small>${e[0]==='01:23:41'?'相机每月与电台报时校准':'记录来源见已登记证物'}</small></div></div>`).join('')}</div><div class="section">录像机校时</div><section class="paper">${state.timeSolved?`<span class="stamp">已校准</span><h3>监控恢复后的显示时间整体快6分钟</h3><p>供电切换导致旧录像机掉电重启，恢复后自动校时失败。录像01:29 / 01:32 / 01:34分别换算为真实时间约01:23 / 01:26 / 01:28。</p>`:unlocked?`<p>你已有录像启动日志、供电切换单和徐洛独立相机原片。录像恢复后有三帧被抄在值班纸上：<b>01:29、01:32、01:34</b>。不要只做减法：先写出可信锚点和设备异常原因，再连续换算三帧。</p><form data-time><label>可信的独立时间锚点：<input name="anchor" placeholder="哪一项材料"></label><label>设备异常原因：<input name="cause" placeholder="用一句话说明"></label><label>监控比真实时间快多少分钟：<input name="offset" inputmode="numeric" placeholder="分钟"></label><div class="equation">录像01:29 → <input name="a" placeholder="真实时间"><br>录像01:32 → <input name="b" placeholder="真实时间"><br>录像01:34 → <input name="c" placeholder="真实时间"></div><div class="actions"><button class="btn paper">提交整段校准</button></div></form>`:`<p>现在还不能校时。至少先取得：录像机启动日志、列车供电切换单、徐洛相机原片。</p>`}</section>`}
function renderPuzzles(){const photoReady=hasEv('S04')&&hasEv('P09');const boxReady=hasEv('S09')&&hasEv('O08')&&hasEv('O01');return pageHead('特殊检验','照片要看见真实裁切痕迹；密码要先算中间量，再组合成锁码。这里不提供现成数字排列。','照片 / 密码箱')+`<div class="photo-grid"><section class="paper"><h2>1994冲印照片检验</h2>${state.photoSolved?`<span class="stamp">检验完成</span><p>左缘二次裁切跨过人物轮廓，残留半截西装袖口与圆形徽章；现存十二张照片无法闭合原画面，因此至少还有第十三人。</p>`:photoReady?`<div class="photo-inspect"><img src="assets/images/old_photo_1994.jpg" alt="1994照片扫描"><button class="photo-edge ${state.photoEdgeFound?'found':''}" data-photo-edge aria-label="检查照片左缘"></button></div>${state.photoEdgeFound?`<p><b>放大后的原始观察：</b>左缘切口穿过一个人物轮廓，只留下半截袖口和圆形金属徽章。不要直接照抄“第十三人”，先写出你看到的残留物，再计算原画面最少人数。</p><form data-photo><label>裁切处残留了什么：<input name="detail" placeholder="用可见物描述"></label><label>原始画面至少有多少人：<input name="count" inputmode="numeric" placeholder="人数"></label><button class="btn paper">记录检验结果</button></form>`:'<p>先在照片上自己找出二次裁切位置。检查区域没有文字箭头，只有鼠标经过或键盘聚焦时才出现边框。</p>'}`:`<p>先取得1994冲印照片组，并用它质证徐洛关于“照片被裁切”的判断。</p>`}</section><section class="paper"><h2>床下四位密码箱</h2>${state.boxOpened?`<span class="stamp">已开启</span><p>登记残页：受试者7人、死亡1人 → 留下6人；公开材料：事故实际发生于11月18日。提示“留下的人 / 那一天” → 0618。</p>${hasEv('B03')?'<p><b>夹层：</b>发现一份资金批示复印件。旧照片中的“第十三人”可能并非普通旁观者。</p>':''}`:boxReady?`<img class="box-photo" src="assets/images/evidence_box.jpg" alt="四位密码箱近照"><p>箱体只有一句手写提示：<b>“留下的人 / 那一天”</b>。注意：“那一天”指事故实际发生日，不是新闻发布日期；“留下的人”也不是总人数。</p><form data-box><div class="calc-grid"><label>受试者总数 <input name="total" inputmode="numeric" placeholder="?"></label><label>死亡人数 <input name="dead" inputmode="numeric" placeholder="?"></label><label>留下的人 <input name="survivors" inputmode="numeric" placeholder="?"></label><label>事故发生日 <input name="day" inputmode="numeric" placeholder="日"></label></div><label>四位锁码 <input name="code" maxlength="4" inputmode="numeric" placeholder="____"></label><button class="btn paper">核算并开锁</button></form>`:`<p>先取得箱体观察、受试者登记残页，以及能核实事故发生日期的公开报道。</p>`}</section></div>`}
function finalReady(){return ['D03','D04','D05','D09','D10'].every(x=>hasDed(x))&&['P14','P20','P22'].every(x=>hasEv(x))}
function renderFinal(){if(state.ending)return renderEnding();const ready=finalReady();const processReady=!!state.choices.tape&&!!state.choices.archive;return pageHead('终夜结案','先核验事实，再让此前对原始材料的处理选择真正决定卷宗如何离开列车。','责任链重建')+`${!ready?`<section class="paper"><h2>事实链尚未闭合</h2><p>至少还需要：死亡机制、刀伤性质、密室形成、可救治窗口，以及三类行为的责任拆分。回到推理板继续组合。</p></section>`:!state.finalSubmitted?`<section class="paper"><h2>结案事实表</h2><p>请用简短事实填写，不要求固定句式。</p><form class="final-form" data-final>${FINAL_FIELDS.map(f=>`<div class="final-field"><label>${f.label}</label><input name="${f.id}" value="${esc(state.finalAnswers[f.id]||'')}" autocomplete="off"></div>`).join('')}<button class="btn primary">提交事实链</button></form></section>`:`<section class="paper"><span class="stamp">事实链通过</span><h2>结局不再由最后一个三选一按钮决定</h2><p>系统会根据你如何处理顾言的原始磁带、以及密码箱旧案材料，生成最终卷宗走向。若此前尚未作出程序选择，可在这里补记。</p>${!state.choices.tape?`<div class="process-choice"><b>原始采访磁带</b><div class="actions"><button class="btn paper" data-choice="tape:seize">扣押原件并制作校验副本</button><button class="btn paper" data-choice="tape:copy">复制校验后归还原件</button></div></div>`:`<p><b>磁带处理：</b>${state.choices.tape==='seize'?'扣押原件并制作校验副本':'复制校验后归还原件'}</p>`}${!state.choices.archive?`<div class="process-choice"><b>旧案材料</b><div class="actions"><button class="btn paper" data-choice="archive:seal">完整封存后正式移交</button><button class="btn paper" data-choice="archive:leak">在移交外留下可验证备份</button></div></div>`:`<p><b>旧案材料：</b>${state.choices.archive==='seal'?'完整封存正式移交':'另留可验证备份'}</p>`}<button class="btn primary" data-seal-report ${processReady?'':'disabled'}>封卷并生成结局</button><p class="tiny">两项程序选择会直接改变结局；隐藏“第十三人”调查会改变尾声信息。</p></section>`}`}
function renderEnding(){const map={legal:['结局一 · 完整卷宗','天亮后，K417恢复通行。你把下药、未施救、死后刺伤、多人进入与外部复位门锁拆成彼此独立的事实条目。原始材料按程序封存，旧案作为另一条责任链重新立案审查。'],truth:['结局二 · 公开的旧档案','江港站到达前，1994年的核心材料已经留下多个可验证副本。公众先看见的是被掩盖十四年的制度责任，而不是一则“密室杀人”的猎奇标题。'],protect:['结局三 · 双轨卷宗','磁带与旧案材料采取了不同的处理路径：一部分严格留在程序内，一部分保留可复核副本。机构责任能够被追问，同时尽量避免让受害者家属再次成为被围观的材料。']};const [title,body]=map[state.ending]||map.protect;const tape=state.choices.tape==='copy'?'顾言保留原始采访磁带，案卷保存校验副本。':'原始磁带封入证物袋，复制校验件进入案卷。';const arc=state.choices.archive==='leak'?'密码箱材料在正式移交之外还留下可验证备份。':'密码箱材料完整封存，开启与复制均有记录。';const secret=hasEv('B03')||state.secret?'沈世勋的资金批示与被裁掉的第十三人，使“旧案只是医护失误”的说法彻底站不住脚。':'照片边缘仍留下一个没有完全回答的问题：谁被从原图里裁掉了？';return `<article class="epilogue"><span class="stamp">CASE CLOSED / 由程序选择生成</span><h2>${title}</h2><p>${body}</p><p>${tape} ${arc}</p><p>${secret}</p><div class="rating"><div><b>${state.evidence.length}</b>证物</div><div><b>${state.deductions.length}</b>推理</div><div><b>${interviewStats().conf}</b>有效质证</div><div><b>${inspectionCount()}</b>现场检查</div></div><div class="actions"><button class="btn paper" data-restart>重新调查</button></div></article>`}
function renderModal(){const m=state.modal;if(!m)return'';if(m.type==='hint'){const h=syncHintContext();const tier=Math.max(1,Math.min(3,state.hintTier||1));return `<div class="overlay hint-overlay" data-close><section class="modal hint-modal" onclick="event.stopPropagation()"><button class="close" data-close>×</button><div class="kicker">K417 / DYNAMIC ASSIST</div><h2>三级调查提示 · ${esc(h.title)}</h2><p class="hint-rule">提示只根据你当前尚未完成的目标变化。一级只给方向，二级定位材料，三级接近解法但不会自动替你登记证物。</p><div class="hint-levels">${h.levels.map((txt,i)=>`<article class="hint-level ${i+1<=tier?'unlocked':'locked'}"><div class="hint-number">${i+1}</div><div><b>${i===0?'一级 · 方向':i===1?'二级 · 定位':'三级 · 接近解法'}</b><p>${i+1<=tier?esc(txt):'尚未展开。'}</p></div></article>`).join('')}</div><div class="actions hint-actions">${tier>1?'<button class="btn" data-hint-less>收回一级</button>':''}${tier<3?'<button class="btn primary" data-hint-more>更具体一点</button>':'<span class="tiny">已展开到三级提示。</span>'}<button class="btn ghost" data-close>收起提示</button></div></section></div>`;}if(m.type==='help')return `<div class="overlay" data-close><section class="modal" onclick="event.stopPropagation()"><button class="close" data-close>×</button><h2>调查方式</h2><ol><li><b>现场：</b>热点只负责靠近。进入近照后检查至少两个局部，并在记录中同时写出两类可见事实。</li><li><b>证人：</b>每人有五项基础问题；关键口供可能需要两到四项材料共同质证，单一“正确证物槽”不再适用于所有问题。</li><li><b>推理：</b>系统按证据角色与逻辑条件核验，同一结论允许多条合理材料路径。</li><li><b>旧网：</b>缓存池包含大量同名与无关结果，检索按完整词组召回。</li><li><b>谜题：</b>时间校准要解释设备异常；照片要描述可见裁切物；密码箱要先核算中间量。</li><li><b>结局：</b>最终走向由前面对原始材料的程序处理决定。</li></ol></section></div>`;if(m.type==='inspect'){const it=INSPECTIONS.find(x=>x.id===m.id);if(!it)return'';const rec=state.inspection[it.id]||{seen:[],note:'',registered:false};return `<div class="overlay" data-close><section class="inspect" onclick="event.stopPropagation()"><button class="close" data-close>×</button><div class="inspect-image evidence-photo"><img src="assets/images/${it.image}" alt="检查${it.label}">${it.spots.map((s,i)=>`<button class="image-marker ${rec.seen.includes(i)?'seen':''}" data-spot="${i}" style="left:${s[2]}%;top:${s[3]}%" aria-label="检查${s[0]}"><span>${i+1}</span></button>`).join('')}</div><div class="inspect-copy"><div class="kicker">PHYSICAL INSPECTION / 物证近照</div><h2>${it.label}</h2><p class="instruction">${it.prompt}</p><div class="spotlist">${it.spots.map((s,i)=>`<button class="spot ${rec.seen.includes(i)?'seen':''}" data-spot="${i}">${i+1}. ${s[0]}</button>`).join('')}</div><div class="obs">${rec.seen.length?rec.seen.map(i=>'· '+it.spots[i][1]).join('<br>'):'尚未放大任何局部。请直接点击照片上的编号或下方检查项。'}</div>${rec.registered?`<p><b>已登记：</b>${EVIDENCE[it.evidence].name}</p>`:`<form class="noteform" data-inspect-note><label>写下至少两类你亲眼看到的事实：</label><input name="note" value="${esc(rec.note||'')}" placeholder="例如：时间/痕迹 + 另一项可见异常"><button class="btn paper">封存观察记录</button></form><p class="tiny">至少检查 ${it.minSpots||2} 个局部；记录必须同时覆盖 ${it.minHits||1} 类关键事实。系统不会接受“可疑”“像谋杀”这类结论性空话。</p>`}</div></section></div>`}if(m.type==='evidence'){const e=EVIDENCE[m.id];if(!e)return'';return `<div class="overlay" data-close><section class="modal" onclick="event.stopPropagation()"><button class="close" data-close>×</button><span class="stamp">${esc(e.type)}</span><h2>${esc(e.name)}</h2><p><b>来源：</b>${esc(e.where)}</p><p>${esc(e.desc)}</p>${hasEv(m.id)?'<p class="tiny">已登记在证物库。</p>':`<button class="btn paper" data-save-ev="${m.id}">阅读完毕，摘录到证物库</button>`}</section></div>`}if(m.type==='doc'){const d=SEARCH_DOCS.find(x=>x.id===m.id);if(!d)return'';return `<div class="overlay" data-close><section class="modal old-doc" onclick="event.stopPropagation()"><button class="close" data-close>×</button><div class="tiny">${d.date} · ${d.kind}</div><h2>${esc(d.title)}</h2><p>${esc(d.snippet)}</p><p>缓存页正文有缺页与乱码。当前可核实信息仅限标题、日期、索引字段和上面的内容摘要；不要把缺失部分自行补成事实。</p>${d.evidence?(hasEv(d.evidence)?'<p><b>这份材料已存入证物库。</b></p>':`<button class="btn paper" data-save-doc="${d.id}">保存可核实摘录</button>`):'<p class="tiny">这条结果没有直接案件价值，可作为排除项。</p>'}</section></div>`}if(m.type==='secret')return `<div class="overlay" data-close><section class="modal old-doc" onclick="event.stopPropagation()"><button class="close" data-close>×</button><div class="tiny">内部索引残页 / 1994</div><h2>项目资金负责人：沈世勋</h2><p>索引显示沈世勋负责当年项目资金审批。与密码箱夹层中的资金批示复印件相互印证后，可以确认他不是普通行政签字人。</p><button class="btn paper" data-confirm-secret>标记隐藏关系</button></section></div>`;return''}
function searchDoc(id){state.modal={type:'doc',id};if(!state.openDocs.includes(id))state.openDocs.push(id);playSfx('radio');save();render()}
function inspectOpen(id){if(!state.inspection[id])state.inspection[id]={seen:[],note:'',registered:false};state.modal={type:'inspect',id};save();render()}
function combineToggle(id){if(state.selectedCombine.includes(id))state.selectedCombine=state.selectedCombine.filter(x=>x!==id);else if(state.selectedCombine.length<5)state.selectedCombine.push(id);else toast('推理板一次最多放5项材料','warn');save();render()}
function deductionMatch(d,set){if(d.logic?.length)return d.logic.every(cl=>cl.any.filter(id=>set.has(id)).length>=(cl.min||1));const paths=d.variants?.length?d.variants:[d.need];return paths.some(v=>v.every(x=>set.has(x)))}
function deductionScore(d,set){if(d.logic?.length){let hit=0,total=0;d.logic.forEach(cl=>{const min=cl.min||1;total+=min;hit+=Math.min(min,cl.any.filter(id=>set.has(id)).length)});return {hit,total}}const paths=d.variants?.length?d.variants:[d.need];const vals=paths.map(v=>({hit:v.filter(x=>set.has(x)).length,total:v.length})).sort((a,b)=>(b.hit/b.total)-(a.hit/a.total)||b.hit-a.hit);return vals[0]||{hit:0,total:1}}
function tryDeduce(){const set=new Set(state.selectedCombine);const candidates=DEDUCTION_RECIPES.filter(d=>!['D02','D08'].includes(d.id)&&!hasDed(d.id)&&deductionMatch(d,set));if(candidates.length){candidates.forEach(d=>addDeduction(d.id));state.selectedCombine=[];save();render();return}const partial=DEDUCTION_RECIPES.filter(d=>!hasDed(d.id)&&!['D02','D08'].includes(d.id)).map(d=>({d,...deductionScore(d,set)})).sort((a,b)=>(b.hit/b.total)-(a.hit/a.total)||b.hit-a.hit)[0];state.hints++;const specific=partial&&partial.hit>=2&&partial.d.logicHint?partial.d.logicHint:'';toast(specific||((partial&&partial.hit>=2)?'这些材料已经靠近同一条事实链，但还缺少能闭合人物、时间或因果关系的支点。':'这组材料暂时不能互相验证。'),'warn');save()}
function handleAsk(qid){const p=PEOPLE.find(x=>x.id===state.person);state.interviews[p.id]=state.interviews[p.id]||{};state.interviews[p.id][qid]=true;addLog(`询问${p.name}：${p.q.find(q=>q[0]===qid)?.[1]||qid}`);save();refreshStage();render()}
function handleConfront(qid){const p=PEOPLE.find(x=>x.id===state.person);const selected=$$(`[data-confront-select="${qid}"]`).map(s=>s.value).filter(Boolean);if(!selected.length)return toast('先选择至少一项已经取得的材料。','warn');const c=p.c.find(x=>x[0]===qid);const paths=confrontPaths(c);const ok=c&&paths.some(path=>path.every(id=>selected.includes(id)));if(ok){state.interviews[p.id]=state.interviews[p.id]||{};state.interviews[p.id]['c:'+qid]=true;addEvidence(c[2],false);addLog(`${p.name}在质证后改口：${EVIDENCE[c[2]]?.name||c[2]}`);playSfx('pencil');toast(c[3],'good');refreshStage();save();render()}else{const key=p.id+':'+qid;state.confrontAttempts[key]=(state.confrontAttempts[key]||0)+1;state.hints++;const best=Math.max(0,...paths.map(path=>path.filter(id=>selected.includes(id)).length));const hint=state.confrontAttempts[key]>=2&&c?.[4]?c[4]:(best?'方向接近，但现有材料还没有把这句话完整闭合。':'这些材料只能证明旁支事实，还压不到这句话本身。');toast(`${p.name}没有改口。${hint}`,'warn');save()}}
function checkInspectNote(it,note){const n=norm(note);if(n.length<6)return false;const groups=it.needGroups?.length?it.needGroups:it.need.map(k=>[k]);const hits=groups.filter(g=>g.some(k=>n.includes(norm(k)))).length;return hits>=(it.minHits||1)}
function doTime(form){const fd=new FormData(form);const anchor=norm(fd.get('anchor')),cause=norm(fd.get('cause'));const off=parseInt(fd.get('offset'),10);const a=norm(fd.get('a')),b=norm(fd.get('b')),c=norm(fd.get('c'));const anchorOK=(anchor.includes('徐洛')||anchor.includes('相机')||anchor.includes('r06'));const causeOK=['供电','掉电','重启'].some(k=>cause.includes(k))&&['校时','时钟','偏移','时间'].some(k=>cause.includes(k));if(anchorOK&&causeOK&&off===TIME_OFFSET&&['0123','123'].includes(a)&&['0126','126'].includes(b)&&['0128','128'].includes(c)){state.timeSolved=true;addDeduction('D02');addLog('录像机整段校准完成：独立相机锚定时钟；供电切换后录像机重启且自动校时失败，显示时间整体快6分钟。');playSfx('pencil');refreshStage();save();render()}else toast('校准未通过。答案必须同时说明：可信锚点、设备为什么发生偏移、偏移量，以及三帧连续换算结果。','warn')}
function doPhoto(form){if(!state.photoEdgeFound)return toast('先实际检查照片左缘的裁切位置。','warn');const fd=new FormData(form);const n=parseInt(fd.get('count'),10);const detail=norm(fd.get('detail'));const visualOK=['袖口','袖','徽章','圆形徽','人物轮廓','裁切'].some(k=>detail.includes(norm(k)));if(n===13&&visualOK){state.photoSolved=true;addEvidence('O12');playSfx('camera');toast('检验成立：可见裁切残留与人数判断相互支持。','good');refreshStage();save();render()}else toast('检验还不完整。先写出裁切边缘真正可见的残留物，再判断原图最少人数。','warn')}
function doBox(form){const fd=new FormData(form);const total=parseInt(fd.get('total'),10),dead=parseInt(fd.get('dead'),10),survivors=parseInt(fd.get('survivors'),10),day=parseInt(fd.get('day'),10);const code=String(fd.get('code')||'').trim();if(total===7&&dead===1&&survivors===6&&day===18&&code===BOX_CODE){state.boxOpened=true;addEvidence('B02');addEvidence('O11');addEvidence('B03');addDeduction('D08');addLog('床下密码箱开启：7名受试者 - 1名死亡 = 6名留下者；事故实际发生日18 → 0618。危机公关方案、封口协议与资金批示进入卷宗。');playSfx('key');refreshStage();save();render()}else if(code===BOX_CODE)toast('锁码碰巧正确，但中间量没有被旧案材料支持；卷宗不接受猜中的密码。','warn');else toast('锁没有打开。分别核对受试者总数、死亡人数、幸存人数与事故实际发生日，再按“留下的人 / 那一天”组合。','warn')}
function answerOK(input,answers){const n=norm(input);if(!n)return false;return answers.some(a=>{const na=norm(a);return n===na||n.includes(na)||na.includes(n)})}
function doFinal(form){const fd=new FormData(form);const wrong=[];FINAL_FIELDS.forEach(f=>{const v=String(fd.get(f.id)||'');state.finalAnswers[f.id]=v;if(!answerOK(v,f.answers))wrong.push(f.label)});if(wrong.length){toast('以下项目仍与证据链不符：'+wrong.join('、'),'warn');save();render();return}state.finalSubmitted=true;addLog('最终事实链核验通过。接下来只处理材料如何离开列车。','04:32');playSfx('pencil');save();render()}
function resolveEnding(){if(!state.choices.tape||!state.choices.archive)return toast('先完成磁带与旧案材料的程序选择。','warn');state.ending=endingFromChoices(state.choices.tape,state.choices.archive);addLog('卷宗根据此前程序选择自动生成最终去向。','04:41');save();render()}
function setAudio(){state.audio=!state.audio;const a=$('#ambience');if(a){a.volume=.2;if(state.audio)a.play().catch(()=>{state.audio=false;save();toast('浏览器阻止了自动播放；不影响游戏。','warn');render()});else a.pause()}save();render()}
function bind(){
  $$('[data-route]').forEach(b=>b.onclick=()=>{state.route=b.dataset.route;state.modal=null;save();render()});
  $('[data-audio]')?.addEventListener('click',setAudio);
  $('[data-help]')?.addEventListener('click',()=>{state.modal={type:'help'};render()});
  $('[data-enter-case]')?.addEventListener('click',()=>{if(!state.started){state.started=true;save()}bootCover=false;state.modal=null;render();scheduleAutoPay()});
  $('[data-reset-case]')?.addEventListener('click',()=>{if(confirm('重置案情会清除当前K417调查进度，并从第一阶段重新开始。确定吗？')){state=baseState();state.started=true;save();bootCover=false;render();scheduleAutoPay()}});
  $('[data-hint]')?.addEventListener('click',()=>{syncHintContext();state.modal={type:'hint'};save();render()});
  $('[data-hint-more]')?.addEventListener('click',()=>{state.hintTier=Math.min(3,(state.hintTier||1)+1);save();render()});
  $('[data-hint-less]')?.addEventListener('click',()=>{state.hintTier=1;save();render()});
  $('[data-support]')?.addEventListener('click',()=>{window.Paywall?.show(supportConfig())});
  $$('[data-close]').forEach(b=>b.onclick=e=>{if(e.currentTarget!==e.target&&e.currentTarget.classList.contains('overlay'))return;state.modal=null;save();render()});
  $$('[data-choice]').forEach(b=>b.onclick=()=>{const [k,v]=b.dataset.choice.split(':');state.choices[k]=v;addLog('程序选择已记录：'+b.textContent.trim());save();render()});
  $$('[data-loc]').forEach(b=>b.onclick=()=>{state.activeLocation=b.dataset.loc;playSfx('foot');save();render()});
  $$('[data-inspect]').forEach(b=>b.onclick=()=>inspectOpen(b.dataset.inspect));
  $$('[data-read-ev]').forEach(b=>b.onclick=()=>{state.modal={type:'evidence',id:b.dataset.readEv};render()});
  $$('[data-save-ev]').forEach(b=>b.onclick=()=>{addEvidence(b.dataset.saveEv);state.modal=null;save();render()});
  $$('[data-spot]').forEach(b=>b.onclick=()=>{const it=INSPECTIONS.find(x=>x.id===state.modal?.id);if(!it)return;const r=state.inspection[it.id]||(state.inspection[it.id]={seen:[],note:'',registered:false});const i=parseInt(b.dataset.spot,10);if(!r.seen.includes(i))r.seen.push(i);playSfx('camera');save();render()});
  $('[data-inspect-note]')?.addEventListener('submit',e=>{e.preventDefault();const it=INSPECTIONS.find(x=>x.id===state.modal?.id);const r=state.inspection[it.id]||(state.inspection[it.id]={seen:[],note:'',registered:false});r.note=String(new FormData(e.currentTarget).get('note')||'').trim();if(r.seen.length<2)return toast('至少先检查两个局部。','warn');if(!checkInspectNote(it,r.note))return toast('记录还太笼统。请写出你确实看到的异常，例如具体痕迹、药名、数量或时间。','warn');r.registered=true;addEvidence(it.evidence);playSfx('pencil');state.modal=null;refreshStage();save();render()});
  $$('[data-person]').forEach(b=>b.onclick=()=>{state.person=b.dataset.person;save();render()});
  $$('[data-ask]').forEach(b=>b.onclick=()=>handleAsk(b.dataset.ask));
  $$('[data-confront]').forEach(b=>b.onclick=()=>handleConfront(b.dataset.confront));
  $$('[data-filter]').forEach(b=>b.onclick=()=>{state.evFilter=b.dataset.filter;save();render()});
  $$('[data-combine]').forEach(b=>b.onclick=()=>combineToggle(b.dataset.combine));
  $('[data-clear-combine]')?.addEventListener('click',()=>{state.selectedCombine=[];save();render()});
  $('[data-deduce]')?.addEventListener('click',tryDeduce);
  $('[data-search]')?.addEventListener('submit',e=>{e.preventDefault();const q=String(new FormData(e.currentTarget).get('q')||'').trim();if(!q)return;state.searchHistory=[q,...state.searchHistory.filter(x=>x!==q)].slice(0,20);playSfx('radio');save();render()});
  $$('[data-doc]').forEach(b=>b.onclick=()=>searchDoc(b.dataset.doc));
  $('[data-save-doc]')?.addEventListener('click',e=>{const d=SEARCH_DOCS.find(x=>x.id===e.currentTarget.dataset.saveDoc);if(d?.evidence)addEvidence(d.evidence);state.modal=null;save();render()});
  $('[data-secret-doc]')?.addEventListener('click',()=>{state.modal={type:'secret'};playSfx('radio');render()});
  $('[data-confirm-secret]')?.addEventListener('click',()=>{state.secret=true;state.modal=null;addLog('隐藏关系确认：沈世勋是1994项目资金负责人。');save();render()});
  $('[data-time]')?.addEventListener('submit',e=>{e.preventDefault();doTime(e.currentTarget)});
  $('[data-photo]')?.addEventListener('submit',e=>{e.preventDefault();doPhoto(e.currentTarget)});
  $('[data-photo-edge]')?.addEventListener('click',()=>{state.photoEdgeFound=true;playSfx('camera');save();render()});
  $('[data-box]')?.addEventListener('submit',e=>{e.preventDefault();doBox(e.currentTarget)});
  $('[data-final]')?.addEventListener('submit',e=>{e.preventDefault();doFinal(e.currentTarget)});
  $('[data-seal-report]')?.addEventListener('click',resolveEnding);
  $('[data-restart]')?.addEventListener('click',()=>{if(confirm('重新调查会清除当前存档。确定吗？')){state=baseState();state.started=true;save();render()}});
}
function render(){refreshStage();const app=$('#app');if(!app)return;if(bootCover||!state.started){app.innerHTML=splash();bind();return}const fn={case:renderCase,map:renderMap,people:renderPeople,evidence:renderEvidence,search:renderSearch,timeline:renderTimeline,puzzles:renderPuzzles,final:renderFinal}[state.route]||renderCase;app.innerHTML=shell(fn());bind()}
function selfTest(){const errors=[];const assert=(c,m)=>{if(!c)errors.push(m)};const exists=id=>EVIDENCE[id]||DEDUCTION_RECIPES.some(d=>d.id===id);assert(PEOPLE.length===12,'人物数量应为12');assert(new Set(PEOPLE.map(p=>p.portrait)).size===12,'12名人物必须使用独立照片');PEOPLE.forEach(p=>{assert(p.q.length>=5,`${p.name}基础询问不足5项`);assert(p.signals?.length>=2,`${p.name}缺少访谈行为观察`);p.c.forEach(c=>{assert(EVIDENCE[c[2]],`${p.name}质证奖励不存在 ${c[2]}`);const paths=confrontPaths(c);assert(paths.length>=1,`${p.name}质证路径为空`);paths.forEach(path=>path.forEach(id=>assert(exists(id),`${p.name}质证前置不存在 ${id}`)))})});INSPECTIONS.forEach(i=>{assert(EVIDENCE[i.evidence],`现场证物不存在 ${i.evidence}`);assert(i.spots.length>=3,`${i.label}观察点不足`);assert(i.needGroups?.length>=2,`${i.label}观察记录未要求两类事实`);assert(i.image&&i.image!=='cabin_scene.jpg',`${i.label}仍复用全景图`);i.spots.forEach(s=>assert(s.length>=4,`${i.label}缺图上标记坐标`))});DEDUCTION_RECIPES.forEach(d=>{const vv=d.variants?.length?d.variants:[d.need];vv.forEach(v=>v.forEach(id=>assert(exists(id),`${d.id}依赖不存在 ${id}`)));(d.logic||[]).forEach(cl=>{assert((cl.min||1)<=cl.any.length,`${d.id}逻辑最小数量超过候选数`);cl.any.forEach(id=>assert(exists(id),`${d.id}逻辑依赖不存在 ${id}`))})});SEARCH_DOCS.forEach(d=>{if(d.evidence)assert(EVIDENCE[d.evidence],`搜索文档证物不存在 ${d.evidence}`)});assert(SEARCH_DOCS.length>=30,'旧网缓存池不足30条');FINAL_FIELDS.forEach(f=>{assert(f.answers.length>0,`终局答案为空 ${f.id}`);assert(answerOK('',f.answers)===false,`终局空答案被错误接受 ${f.id}`)});assert(searchResults('安济 1994').some(d=>d.id==='clinic94'),'安济1994精确搜索失败');assert(searchResults('周柏年 说明会').some(d=>d.id==='meeting'),'说明会搜索失败');assert(!searchResults('韩雪琴').some(d=>d.id==='clinic94'),'单字重合造成错误强召回');assert(DEDUCTION_RECIPES.find(d=>d.id==='D08')?.need.includes('O01'),'密码推理未要求事故日期');assert(EVIDENCE.O01.desc.includes('11月18'),'事故发生日未写入公开材料');assert(TIME_OFFSET===6,'时间偏移常量错误');assert(BOX_CODE==='0618','密码常量错误');assert(checkInspectNote(INSPECTIONS.find(i=>i.id==='watch'),'1:31停表且表壳有新凹痕'),'现场双事实记录校验失败');assert(!checkInspectNote(INSPECTIONS.find(i=>i.id==='watch'),'很可疑'),'空泛现场结论被错误接受');const han=PEOPLE.find(p=>p.id==='han').c.find(c=>c[0]==='trip');assert(confrontPaths(han).some(x=>x.length>=3),'关键下药质证仍是单证物槽');const d5=DEDUCTION_RECIPES.find(d=>d.id==='D05');assert(deductionMatch(d5,new Set(['R08','P05','P07'])),'多人密室等价推理路径失败');assert(endingFromChoices('seize','seal')==='legal','依法结局映射错误');assert(endingFromChoices('copy','leak')==='truth','公开结局映射错误');assert(endingFromChoices('copy','seal')==='protect','双轨结局映射错误');assert(hintProfile().levels.length===3,'三级提示数量错误');assert(typeof window.Paywall!=='undefined','付款系统未加载');['case','map','people','evidence','search','timeline','puzzles','final'].forEach(r=>{try{({case:renderCase,map:renderMap,people:renderPeople,evidence:renderEvidence,search:renderSearch,timeline:renderTimeline,puzzles:renderPuzzles,final:renderFinal}[r])()}catch(e){errors.push(`页面渲染失败 ${r}: ${e.message}`)}});return {ok:!errors.length,errors,stats:{people:PEOPLE.length,evidence:Object.keys(EVIDENCE).length,inspections:INSPECTIONS.length,deductions:DEDUCTION_RECIPES.length,searchDocs:SEARCH_DOCS.length,stages:STAGES.length,questions:PEOPLE.reduce((n,p)=>n+p.q.length,0)}}}
function flowTest(){const s=baseState();s.started=true;const add=id=>{if(!s.evidence.includes(id))s.evidence.push(id)};const ded=id=>{if(!s.deductions.includes(id))s.deductions.push(id)};const mark=(pid,key)=>{s.interviews[pid]=s.interviews[pid]||{};s.interviews[pid][key]=true};const steps=[];const ck=(expected,label)=>{const got=computeStage(s);steps.push({label,expected,got,ok:got===expected});return got===expected};INSPECTIONS.slice(0,5).forEach(i=>s.inspection[i.id]={seen:[0,1],note:i.need[0],registered:true});['R01','R02'].forEach(add);ck(2,'现场与列车记录');['lin','chen','gu','xu'].forEach(pid=>mark(pid,'trip'));['R06','R10'].forEach(add);ck(3,'四人询问与独立照片');['O01','O03','O04'].forEach(add);ck(4,'旧案材料');s.timeSolved=true;ded('D02');ck(5,'时间校准');['S03','S08','F02','F03','S06','F01'].forEach(add);ded('D03');ded('D04');ck(6,'死亡机制');['lin','chen','gu'].forEach((pid,i)=>mark(pid,'c:x'+i));s.photoSolved=true;s.boxOpened=true;add('O12');ck(7,'质证照片密码箱');['P14','P20','P22'].forEach(add);ded('D10');ck(8,'责任拆分');const ok=steps.every(x=>x.ok);return {ok,steps}}
window.__K417_SELFTEST__=selfTest;window.__K417_FLOWTEST__=flowTest;window.__K417_DEBUG_STATE__=()=>clone(state);
const params=new URLSearchParams(location.search);if(params.get('test')==='1'||params.get('test')==='flow'){document.addEventListener('DOMContentLoaded',()=>{const result=params.get('test')==='flow'?flowTest():selfTest();document.body.innerHTML=`<pre id="test-report" class="test-report">${esc(JSON.stringify(result,null,2))}</pre>`;document.title=result.ok?'PASS':'FAIL'});}else document.addEventListener('DOMContentLoaded',render);
})();
